import{_ as l,c as e,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"雷山小过","description":"周易折中 - 雷山小过","frontmatter":{"title":"雷山小过","description":"周易折中 - 雷山小过"},"headers":[],"relativePath":"zh/classics/zhezhong/068.md","filePath":"zh/classics/zhezhong/068.md"}'),h={name:"zh/classics/zhezhong/068.md"};function p(n,a,d,t,s,o){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="雷山小过" tabindex="-1">雷山小过 <a class="header-anchor" href="#雷山小过" aria-label="Permalink to “雷山小过”">​</a></h1><h3 id="程传" tabindex="-1">程传 <a class="header-anchor" href="#程传" aria-label="Permalink to “程传”">​</a></h3><p>〈小过序卦〉：“有其信者必行之，故受之以《小过》。人之所信，则必行；行，则过也。《小过》所以继《中孚》也。为卦，山上有雷，雷振于高，其声过常，故为《小过》。又阴居尊位，阳失位而不中，小者过其常也。葢为小者过，又为小事过，又为过之小。”</p><p>小过：亨，利贞。可小事，不可大事。飞鸟遗之音，不宜上，宜下，大吉。</p><h3 id="本义" tabindex="-1">本义 <a class="header-anchor" href="#本义" aria-label="Permalink to “本义”">​</a></h3><p>小谓阴也，为卦四阴在外，二阳在内，阴多于阳，小者过也。既过于阳，可以亨矣，然必利于守贞，则又不可以不戒也。卦之二五皆以柔而得中，故可小事；三四皆以刚失位而不中，故不可大事。卦体内实外虚，如鸟之飞，其声下而不上，故能致飞鸟遗音之应，则宜下而大吉，亦不可大事之类也。</p><h3 id="程传-1" tabindex="-1">程传 <a class="header-anchor" href="#程传-1" aria-label="Permalink to “程传”">​</a></h3><p>过者，过其常也。若矫枉而过正，过所以就正也。事有时而当然，有待过而后能亨者，故小过自有亨义。利贞者，过之道利于贞也，不失时宜之谓正。过所以求就中也，所过者小事也，事之大者岂可过也？于大过论之详矣。飞鸟遗之音，谓过之不远也。不宜上，宜下，谓宜顺也，顺则大吉。过以就之，葢顺理也，过而顺理，其吉必大。</p><h3 id="集说" tabindex="-1">集说 <a class="header-anchor" href="#集说" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰：飞鸟遗其音，声哀以求处，上愈无所适，下则得安。愈上则愈穷，莫若飞鸟也。</p></li><li><p>孔氏颖达曰：过之小事，谓之小过，即行过乎恭、丧过乎哀之例是也。禇氏云：谓小人之行小有过差，君子为过厚之行以矫之，如晏子狐裘之比也。过为小事，道乃可通，故曰“小过亨，利贞者，矫世励俗，利在归正也”。可小事不可大事者，小有过差，惟可矫以小事，不可正以大事。飞鸟遗之音，不宜上宜下大吉者，飞鸟声哀以求处，上过则愈无所适，过下则不失其安。譬君子处过差之时，为过矫之行，顺则执卑守下，逆则犯君陵上，故以顺逆类鸟之上下也。</p></li><li><p>吕氏大临曰：小过，过于小者也。君子之道皆以济其不及，然后可以㑹于中。大过以济其大不及，小过以济其小不及者，济所以亨也。飞鸟不宜上宜下，上穷而下有止也。过奢过慢则凶，不宜上也；过恭过俭则吉，宜下也。</p></li><li><p>朱子语类云：小过是过于慈惠之类，大过则是刚严果毅底气象。小过是小事过，又是过于小，如行过乎恭、丧过乎哀、用过乎俭，皆是过于小，退后一步自贬底意思。</p></li><li><p>俞氏琰曰：小过之时，可过者小事而已，大事则不可过也。</p></li><li><p>林氏希元曰：小过不当以人类言，当以事类言。观大象，本义曰“三者之过皆小者之过”，可过于小而不可过于大，可以小过而不可以甚过。又曰：“彖所谓可小事而宜下，其意可见矣。”小过亨者，小事过而亨也。曰“利贞”，深戒占者之辞。可小事不可大事，是申小过之义。言此卦之义可以施于小事，不可施于大事。不宜上宜下，又是申利贞之义。飞鸟遗之音者，卦有飞鸟之象，卦示以兆，如飞鸟之遗以音也。上下二字是借鸟飞之上下以切人事。飞鸟相呼云“不宜上宜下”，在飞鸟则上无止戾，下有栖宿；在人事则髙亢者失正而远于理，卑约者得正而近乎情，是以大吉也。</p></li><li><p>陆氏铨曰：君子虽行贵得中，事期当可，然势有极重时，须损馀以补缺。事必矫枉而后平，即夫子所谓宁俭宁戚之意。理所当过，即是时中。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>大过者，大事过也；小过者，小事过也。大事谓关系天下国家之事，小事谓日用常行之事。道虽贵中，而有时而过者，过所以为中也。当过而过，然后可以通行，故有亨道而利于正也。可小事不可大事，是申小过之义，言此卦之义可以施于小事，不可施于大事。不宜上宜下，又是申利贞之义。飞鸟遗之音，者卦有飞鸟之象，卦示以兆，如飞鸟之遗以音也。上下二字是借鸟飞之上下以切人事。飞鸟相呼云“不宜上宜下”，在飞鸟则上无止戾，下有栖宿；在人事则髙亢者失正而远于理，卑约者得正而近乎情，是以大吉也。</p><p>象曰：山上有雷，小过；君子以行过乎恭，丧过乎哀，用过乎俭</p><h3 id="本义-1" tabindex="-1">本义 <a class="header-anchor" href="#本义-1" aria-label="Permalink to “本义”">​</a></h3><p>山上有雷，其声小过。三者之过，皆小者之过。可过于小而不可过于大，可以小过而不可甚过。彖所谓“可小事而宜下者也”。</p><h3 id="程传-2" tabindex="-1">程传 <a class="header-anchor" href="#程传-2" aria-label="Permalink to “程传”">​</a></h3><p>雷震于山上，其声过常，故为小过。天下之事，有时当过而不可过甚，故为小过。君子观小过之象，事之宜过者则勉之。行过乎恭，丧过乎哀，用过乎俭是也。当过而过，乃其宜也；不当过而过，则过矣。</p><h3 id="集说-1" tabindex="-1">集说 <a class="header-anchor" href="#集说-1" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰 ：小人过差，失在慢易奢侈，故君子矫之以行过乎恭，丧过乎哀，用过乎俭也。</p></li><li><p>张子曰 ：过恭、哀、俭，皆宜下之义。</p></li><li><p>鼂氏说之曰 ：时有举趾高之莫敖，故正考父矫之以循墙；时有短丧之宰予，故高柴矫之以泣血；时有三归反坫之管仲，故晏子矫之以敝裘。虽非中行，亦足以矫时厉俗。</p></li><li><p>赵氏彦肃曰 ：恭、哀、俭多不及，过之而后中。</p></li><li><p>杨氏启新曰 ：过恭、过哀、过俭，此岂不为高世绝俗之行而过乎人？但其所过者以收敛卑下为过，故但可言小过而不可言大过也。案雷出地则声方发达而大，及至山上则声渐收敛而微，故有平地风雷大作而高山之上不觉者，此小过之义也。</p></li></ul><p>彖曰：小过 小者过而亨也</p><h3 id="本义-2" tabindex="-1">本义 <a class="header-anchor" href="#本义-2" aria-label="Permalink to “本义”">​</a></h3><p>以卦体释卦名义与其辞。</p><h3 id="程传-3" tabindex="-1">程传 <a class="header-anchor" href="#程传-3" aria-label="Permalink to “程传”">​</a></h3><p>阳大阴小，阴得位，刚失位而不中，是小者过也。故为小事过，过之小。小者与小事有时而当过，过之亦小，故为小过。事固有待过而后能亨者，过之所以能亨也。</p><h3 id="集说-2" tabindex="-1">集说 <a class="header-anchor" href="#集说-2" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖逹曰：顺时矫俗，虽过而通。</p></li><li><p>朱氏震曰：小过，小者过也。葢事有失之于偏，矫其失必待小有所过，然后偏者反于中。谓之过者，比之常理则过也，过反于中，则其用不穷而亨矣。故曰“小者过而亨也”。</p></li><li><p>王氏宗传曰：言以过故亨也。天下固有越常救失之事，如象所谓“过乎恭”、“过乎哀”、“过乎俭”是也。不有所过，安能亨哉？故曰“小者过而亨也”。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>此释义与“遁而亨也”同。遁非得已之事，然必遁而后亨；小过亦非得已之事，然必过而后亨，故其释义同也。</p><p>过以利贞，与时行也</p><h3 id="程传-4" tabindex="-1">程传 <a class="header-anchor" href="#程传-4" aria-label="Permalink to “程传”">​</a></h3><p>过而利于贞，谓与时行也。时当过而过，乃非过也，时之宜也，乃所谓正也。</p><h3 id="集说-3" tabindex="-1">集说 <a class="header-anchor" href="#集说-3" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>苏氏轼曰：彖之所谓“利贞”，即象之所谓“过乎恭俭与哀”者，时当然也。</p></li><li><p>朱氏震曰：君子制事以天下之正理，所以小过者，时而已。故曰“过以利贞，与时行也”。</p></li><li><p>蔡氏渊曰：与时行，谓随小过之时而用其正也。</p></li><li><p>龚氏焕曰：道贵得中，过非所尚。然随时之宜，施当其可，则过也乃所以为中也。故曰“过以利贞，与时行也”。与时行而不失其贞，则过非过矣。</p></li></ul><p>柔得中是以小事吉也</p><h3 id="本义-3" tabindex="-1">本义 <a class="header-anchor" href="#本义-3" aria-label="Permalink to “本义”">​</a></h3><p>以二五言。</p><p>刚失位而不中是以不可大事也</p><h3 id="本义-4" tabindex="-1">本义 <a class="header-anchor" href="#本义-4" aria-label="Permalink to “本义”">​</a></h3><p>以三四言。</p><h3 id="程传-5" tabindex="-1">程传 <a class="header-anchor" href="#程传-5" aria-label="Permalink to “程传”">​</a></h3><p>小过之道，于小事有过则吉者。而彖以卦才言吉义，柔得中，二五居中也。阴柔得位，能致小事吉耳，不能济大事也。刚失位而不中，是以不可大事。大事非刚阳之才不能济，三不中，四失位，是以不可大事。小过之时，自不可大事，而卦才又不堪大事，与时合也。</p><h3 id="集说-4" tabindex="-1">集说 <a class="header-anchor" href="#集说-4" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖逹曰：柔顺之人能行小事，柔而得中是行小中时，故曰“小事吉也”。刚健之人能行大事，失位不中是行大不中时，故曰“不可大事也”。</p></li><li><p>朱氏震曰：于小事有过而不失其正则吉，柔得中也。作大事非刚得位得中不能济，失位则无所用其刚，不中则才过乎刚，是以小过之时不可作大事也。</p></li><li><p>胡氏炳文曰：矫天下之枉者，以过为正。然刚过而中为大过，柔得中为小过。是则事有当过者，而皆不可外乎中也。</p></li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>任大事贵刚，取其强毅可以遗大投艰也；处小事贵柔，取其畏慎为能矜细勤小也。二者皆因乎时，得中者适乎时之谓也。此卦柔得中，刚失位而不中，则有行小事适时而行大事则非其时之象。</p><p>有飞鸟之象焉，飞鸟遗之音，不宜上，宜下，大吉；上逆而下顺也</p><h3 id="本义-5" tabindex="-1">本义 <a class="header-anchor" href="#本义-5" aria-label="Permalink to “本义”">​</a></h3><p>以卦体言。</p><h3 id="程传-6" tabindex="-1">程传 <a class="header-anchor" href="#程传-6" aria-label="Permalink to “程传”">​</a></h3><p>有飞鸟之象焉，此一句不类彖体，盖解者之辞误入彖中。中刚外柔，飞鸟之象，卦有此象，故就飞鸟为义。事有时而当过，所以从宜，然岂可甚过也？如过恭、过哀、过俭，大过则不可。所以在小过也，所过当如飞鸟之遗音。鸟飞迅疾，声出而身已过，然岂能相远也？事之当过者亦如是，身不能甚远于声，事不可远过其常，在得宜耳。不宜上，宜下，更就鸟音取宜顺之义。过之道当如飞鸟之遗音，夫声逆而上则难，顺而下则易。故在髙则大过，山上有雷所以为过也。过之道顺行则吉，如飞鸟之遗音，宜顺也。所以过者为顺乎宜也，能顺乎宜所以大吉。</p><h3 id="集说-5" tabindex="-1">集说 <a class="header-anchor" href="#集说-5" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰：施过于不顺，凶莫大焉；施过于顺，过更变而为吉也。</p></li><li><p>胡氏瑗曰：四阴在外，二阳在内，是内实外虚，故有飞鸟之象也。飞鸟翔空无所依著，愈上则愈穷，是上则逆也；下附物则身可安，是下则顺也。犹君子之人过行其事以矫世励俗，必下附人情，亦宜下而不宜上也。</p></li><li><p>朱氏震曰：上逆也，故不宜上；下顺也，故宜下。小过之时，事有时而当过，所以从宜，不可过越已甚，不然必凶也。</p></li><li><p>俞氏琰曰：溯风而上为逆，随风而下为顺。</p></li><li><p>方氏时化曰：圣人因此卦有飞鸟之象，遂即象以戒之曰：“飞鸟有遗音。”云“遗音如何言不宜上，宜下大吉”云耳。夫鸟上飞则逆，下飞则顺，其大致也。今自谓宜下而不宜上焉，实为二阳讽也。</p></li><li><p>吴氏曰慎曰：以卦体言，阴乘阳为逆，承阳为顺。四阴分居上下，有逆顺之象。</p></li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>四阳居中则有栋梁之象，四阴居外则有羽毛之象。君子之任大事，则为天下栋梁；修细行，则为天下羽仪。此二卦取象之意也。然以其阴阳皆过多也，故谓之大过、小过。事固有过以为中者，无嫌于过也，然必过而不失其中，乃归于无过。故栋则恶其太刚而折，太重而桡，故宜隆于上不可桡于下也；羽则恶其柔而无立，轻而不戢，故宜就于下不可飏于上也。大过之彖曰：“刚过而中，不桡乎下，斯为刚之中矣。”小过之彖曰：“柔得中，不宜上，宜下，斯为柔之中矣。”</p><p>初六：飞鸟以凶</p><h3 id="本义-6" tabindex="-1">本义 <a class="header-anchor" href="#本义-6" aria-label="Permalink to “本义”">​</a></h3><p>初六阴柔，上应九四，又居过时上而不下者也。飞鸟遗音，不宜上宜下，故其象占如此。郭璞《洞林》占得此者，或致羽虫之孽。</p><h3 id="程传-7" tabindex="-1">程传 <a class="header-anchor" href="#程传-7" aria-label="Permalink to “程传”">​</a></h3><p>初六阴柔在下，小人之象，又上应于四。四复动体，小人躁易，而上有应，助于所当过，必至过甚。况不当过而过，其过如飞鸟之迅疾，所以凶也。躁疾如是，所以过之速且远，救止莫及也。</p><h3 id="集说-6" tabindex="-1">集说 <a class="header-anchor" href="#集说-6" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰：小过之义，上逆下顺。而初应在上卦，进而之逆，同于飞鸟无所错足，故曰“飞鸟以凶”。</p></li><li><p>胡氏瑗曰：小过之时不宜上位，在下而志愈上，故获凶也。</p></li><li><p>项氏安世曰：初上二爻阴过而不得中，是以凶也。以卦象观之，二爻皆当鸟翅之末。初六在艮之下，当止而反飞，以飞致凶，故曰“飞鸟以凶”。上六居震之极，其飞已高，则丽于纲罟，故曰“飞鸟离之凶”。</p></li><li><p>龚氏焕曰：大过卦辞以栋为象，而三四两爻亦以栋言；小过卦辞以鸟为象，而初上两爻亦以鸟言。大过阳过于中，而三四又阳之中也；小过阴过于外，初上又阴之外也。</p></li><li><p>胡氏炳文曰：大过有栋桡象，栋之用在中，故于三四言之。小过有飞鸟象，鸟之用在翼，故于初上言之。然初二五上皆翼也，独初上言之何耶？鸟飞不在翼而在翰，初上其翰也。</p></li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>大过象栋者两爻，小过象飞鸟者亦两爻。然大过宜隆不宜桡，则四居上吉，三居下凶，宜矣。小过之鸟宜下不宜上，初居下应吉而反凶者，何也？盖屋之中栋惟一而已，四之象独当之；鸟之翼则有两，初与上之象皆当之也。初于时则未过，于位则处下，如鸟之正当栖宿者，乃不能自禁而飞，其凶也岂非自取乎？</p><p>象曰：飞鸟以凶，不可如何也</p><h3 id="程传-8" tabindex="-1">程传 <a class="header-anchor" href="#程传-8" aria-label="Permalink to “程传”">​</a></h3><p>其过之疾如飞鸟之迅，岂容救止也？凶其宜矣，不可如何，无所用其力也。</p><h3 id="集说-7" tabindex="-1">集说 <a class="header-anchor" href="#集说-7" aria-label="Permalink to “集说”">​</a></h3><ul><li>何氏楷曰 ：以凶者自纳于凶也，孽由己作，可如何哉？</li></ul><p>六二：过其祖，遇其妣；不及其君，遇其臣，无咎。</p><h3 id="本义-7" tabindex="-1">本义 <a class="header-anchor" href="#本义-7" aria-label="Permalink to “本义”">​</a></h3><p>六二柔顺中正，进则过三四而遇六五，是过阳而反遇阴也。如此则不及六五而自得其分，是不及君而适遇其臣也。皆过而不过，守正得中之意，无咎之道也。故其象占如此。</p><h3 id="程传-9" tabindex="-1">程传 <a class="header-anchor" href="#程传-9" aria-label="Permalink to “程传”">​</a></h3><p>阳之在上者，父之象；尊于父者，祖之象。四在三上，故为祖。二与五居相应之地，同有柔中之德，志不从于三四，故过四而遇五，是过其祖也。五阴而尊，祖妣之象。与二同德相应，在他卦则阴阳相求，过之时必过其常，故异也。无所不过，故二从五，亦戒其过。不及其君遇其臣，谓上进而不陵及于君，适当臣道，则无咎也。遇，当也。过臣之分，则其咎可知。</p><h3 id="集说-8" tabindex="-1">集说 <a class="header-anchor" href="#集说-8" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏宗传曰：六二或过或不及，皆适当其时与分，而不愆于中焉。此在过之道，为无过也，故曰无咎。</p></li><li><p>俞氏琰曰：遇妣而过于祖，虽过之，君子不以为过也。遇臣则不可过于君，故曰“不及其君遇其臣”。彖言“可小事不可大事，不宜上宜下”，而六二柔顺中正，故其象如此，其占无咎。</p></li><li><p>张氏振渊曰：祖妣只作阴阳象，阳亢而阴顺也。过祖遇妣，是去阳而就阴，去亢而从顺。如此则不陵及于君，适当臣道之常矣。不及其君遇其臣，宜下宜顺也。</p></li><li><p>吴氏曰愼曰：六二中正而爻辞以过不及言之，葢当过而过，当不及而不及，此权之所以取中，而卒无过不及之偏矣。</p></li></ul><h3 id="案-5" tabindex="-1">案 <a class="header-anchor" href="#案-5" aria-label="Permalink to “案”">​</a></h3><p>古者重昭穆，故孙则祔于祖，孙妇则袝于祖姑。晋之王母，此爻之“妣”，皆谓祖姑也。两阴相应，故取妣妇相配之象。凡《易》之义，阴阳有应者则为君臣、为夫妇，取其耦配也；无应者则或为父子、或为等夷、或为嫡媵、或为妣妇，取其同类也。此爻二五皆柔，有妣妇之配，无君臣之交，故取“遇妣不及其君”为义。孙行而附于祖列，疑其过矣，然礼所当然是适得其分也。无应于君者，不敢仰干于君之象，然守柔居下，是臣节不失也。以人事类之，则事之可过者，过而得其恭顺之体；事之必不可过者，不及而安于名分之常。夫子之言“麻冕拜下”，意正如此也。小过之义主于过恭过俭，妻道也，臣道也。二当其位而有中正之德，故能权衡于过不及而得其中。于六爻中，为最善。</p><p>象曰：不及其君臣，不可过也</p><h3 id="本义-8" tabindex="-1">本义 <a class="header-anchor" href="#本义-8" aria-label="Permalink to “本义”">​</a></h3><p>所以不及君而还遇臣者，以臣不可过故也。</p><h3 id="程传-10" tabindex="-1">程传 <a class="header-anchor" href="#程传-10" aria-label="Permalink to “程传”">​</a></h3><p>过之时，事无不过其常。故于上进，则戒及其君臣，不可过臣之分也。</p><h3 id="集说-9" tabindex="-1">集说 <a class="header-anchor" href="#集说-9" aria-label="Permalink to “集说”">​</a></h3><ul><li>胡氏炳文曰 ：小者有时而可过，臣之于君，不可过也。</li></ul><p>九三：弗过防之，从或戕之，凶。</p><h3 id="本义-9" tabindex="-1">本义 <a class="header-anchor" href="#本义-9" aria-label="Permalink to “本义”">​</a></h3><p>小过之时，事每当过然后得中。九三以刚居正，众阴所欲害者也。而自恃其刚，不肯过为之备，故其象占如此。若占者能过防之，则可以免矣。</p><h3 id="程传-11" tabindex="-1">程传 <a class="header-anchor" href="#程传-11" aria-label="Permalink to “程传”">​</a></h3><p>小过，阴过阳失位之时，三独居正。然在下无所能为，而为阴所忌恶。故有当过者，在过防于小人。若弗过防之，则或从而戕害之矣，如是则凶也。三于阴过之时，以阳居刚，过于刚也。既戒之过防，则过刚亦在所戒矣。防小人之道，正己为先。三不失正，故无必凶之义。能过防则免矣。三居下之上，居上为下，皆如是也。</p><h3 id="集说-10" tabindex="-1">集说 <a class="header-anchor" href="#集说-10" aria-label="Permalink to “集说”">​</a></h3><p>杨氏启新曰：此言当过于防，而九三不知时也。</p><h3 id="案-6" tabindex="-1">案 <a class="header-anchor" href="#案-6" aria-label="Permalink to “案”">​</a></h3><p>小过者，小事过也。小事过者，敬小慎微之义也。九三过刚，违于斯义矣，故为“不过于周防而或遇戕害”之象。《传》曰：“君子能勤小物，故无大患。”此爻之义也。</p><p>象曰：从或戕之，凶，如何也</p><h3 id="程传-12" tabindex="-1">程传 <a class="header-anchor" href="#程传-12" aria-label="Permalink to “程传”">​</a></h3><p>阴过之时，必害于阳。小人道盛，必害君子。当过为之防，防之不至，则为其所戕矣。故曰凶，如何也？言其甚也。</p><p>九四：无咎，弗过遇之，往厉必戒，勿用永贞。</p><h3 id="本义-10" tabindex="-1">本义 <a class="header-anchor" href="#本义-10" aria-label="Permalink to “本义”">​</a></h3><p>当过之时，以刚处柔，过乎恭矣。无咎之道也。弗过遇之，言弗过于刚而适合其宜也。往则过矣，故有厉而当戒。阳性坚刚，故又戒以勿用永贞。言当随时之宜，不可固守也。或曰：弗过遇之，若以六二爻例，则当如此说；若依九三爻例，则过遇当如过防之义。未详孰是，当阙以俟知者。</p><h3 id="程传-13" tabindex="-1">程传 <a class="header-anchor" href="#程传-13" aria-label="Permalink to “程传”">​</a></h3><p>四当小过之时，以刚处柔，刚不过也是以无咎。既弗过，则合其宜矣，故云遇之，谓得其道也。若往则有危，必当戒惧也，往去柔而以刚进也。勿用永贞，阳性坚刚，故戒以随宜不可固守也。方阴过之时，阳刚失位，则君子当随时顺处，不可固守其常也。四居高位而无上下之交，虽比五应初，方阴过之时，彼岂肯从阳也，故往则有厉。</p><h3 id="集说-11" tabindex="-1">集说 <a class="header-anchor" href="#集说-11" aria-label="Permalink to “集说”">​</a></h3><ul><li>朱子语类云：过遇犹言加意待之也，与九三“弗过防之”文体正同。</li></ul><h3 id="案-7" tabindex="-1">案 <a class="header-anchor" href="#案-7" aria-label="Permalink to “案”">​</a></h3><p>彖传三四皆刚失位而不中，然九三纯刚故凶，九四居柔故有无咎之义。然质本刚也，故又戒以当过遇之为善。遇者，合人情就事理。过遇，朱子所谓加意待之者是也。若不能过遇之，则往而有危，所当以为戒而不可固执而不变者，是小过之时义也。</p><p>象曰：弗过遇之，位不当也；往厉必戒，终不可长也</p><h3 id="本义-11" tabindex="-1">本义 <a class="header-anchor" href="#本义-11" aria-label="Permalink to “本义”">​</a></h3><p>爻义未明，此亦当阙。</p><h3 id="程传-14" tabindex="-1">程传 <a class="header-anchor" href="#程传-14" aria-label="Permalink to “程传”">​</a></h3><p>位不当，谓处柔。九四当过之时，不过刚而反居柔，乃得其宜，故曰遇之，遇其宜也。以九居四位不当也，居柔乃遇其宜也。当阴过之时，阳退缩自保足矣，终岂能长而盛也？故往则有危，必当戒也。“长”上声作平声，则大失易意，以夬与剥观之可见。与夬之象文同而音异也。</p><h3 id="集说-12" tabindex="-1">集说 <a class="header-anchor" href="#集说-12" aria-label="Permalink to “集说”">​</a></h3><ul><li>钱氏一本曰 ：三四皆失位，故特明其位不当。三防，四遇，亦皆宜下。三从或戕，四往必戒，亦皆不宜上。</li></ul><h3 id="案-8" tabindex="-1">案 <a class="header-anchor" href="#案-8" aria-label="Permalink to “案”">​</a></h3><p>位不当，即所谓刚失位而不中者。惟刚失位而不中，故戒以当过遇之，不然则有危矣。岂可长执此而不知变乎？</p><p>六五：密云不雨，自我西郊。公弋取彼在穴。</p><h3 id="本义-12" tabindex="-1">本义 <a class="header-anchor" href="#本义-12" aria-label="Permalink to “本义”">​</a></h3><p>以阴居尊，又当阴过之时，不能有为。而弋取六二以为助，故有此象。在穴，阴物也。两阴相得，其不能济大事可知。</p><h3 id="程传-15" tabindex="-1">程传 <a class="header-anchor" href="#程传-15" aria-label="Permalink to “程传”">​</a></h3><p>五以阴柔居尊位，虽欲过为，岂能成功？如宻云而不能成雨，所以不能成雨自西郊故也。阴不能成雨，小畜卦中已解。公弋取彼在穴，弋射取之也。射止是射，弋有取义。穴，山中之空，中虚乃空也。在穴，指六二也。五与二本非相应，乃弋而取之。五当位，故云公，谓公上也。同类相取，虽得之，两阴岂能济大事乎？犹密云之不能成雨也。</p><h3 id="集说-13" tabindex="-1">集说 <a class="header-anchor" href="#集说-13" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>张子曰：小过有飞鸟之象，故因曰“取彼在穴”。</p></li><li><p>胡氏瑗曰：弋者，所以射高也；穴者，所以隐伏而在下也。公以弋缴而取穴中之物，犹圣贤虽过行其事，意在矫下也。</p></li><li><p>姚氏舜牧曰：时值小过，宜下不宜上。阴至于五，过甚矣。其所居者尊位也，挟势自亢，泽不下究。云虽密而不雨，自我西郊故耳。当此之时，欲沛膏泽于生民，必湏下求岩穴之士以为辅，乃可也。故又戒之以求助，抑之以下贤。</p></li><li><p>钱氏志立曰：小过所恶者，飞鸟也。鸟在穴而不飞，所谓不宜上而宜下者也。故公弋取以为助。</p></li></ul><h3 id="案-9" tabindex="-1">案 <a class="header-anchor" href="#案-9" aria-label="Permalink to “案”">​</a></h3><p>小过有飞鸟之象，而所恶者飞，盖飞则上而不下，违乎不宜上宜下之义也。云亦飞物也，下而降则为雨。密云不雨，是犹飞而未下也。五在上体，又居尊位，当小过之时，上而未下者也。故取宻云不雨为象。云而不雨，则膏泽不下于民矣。以其虚中也，故能降心以从道，抑志以下交，如弋鸟然。不弋其飞者而弋其在穴者，如此则合乎宜下之义，而云之飞者不崇朝而为雨之润矣。此爻变鸟之象而为云者，以居尊位故也。</p><p>象曰：密云不雨，已上也</p><h3 id="本义-13" tabindex="-1">本义 <a class="header-anchor" href="#本义-13" aria-label="Permalink to “本义”">​</a></h3><p>已上，太高也。</p><h3 id="程传-16" tabindex="-1">程传 <a class="header-anchor" href="#程传-16" aria-label="Permalink to “程传”">​</a></h3><p>阳降阴升，合则和而成雨。阴已在上，云虽密岂能成雨乎？阴过不能成大之义也。</p><h3 id="集说-14" tabindex="-1">集说 <a class="header-anchor" href="#集说-14" aria-label="Permalink to “集说”">​</a></h3><ul><li>龚氏焕曰 ：密云不雨，小畜谓其尚往者，阴不足以畜阳而阳尚往也；小过谓其已上者，阴过乎阳而阴已上也。一为阳之过，一为阴之过，皆阴阳不和之象，所以不能为雨也。案两卦密云不雨，龚氏谓皆阴阳不和之象是已然。小畜所谓尚往者，亦是阴气上行，与此爻已上同，非两义也。但小畜卦义喻在下者，则尚往者当积厚而自雨；此爻之义喻在上者，则已上者当下交而乃雨，意义不同尔。</li></ul><p>上六：弗遇过之，飞鸟离之，凶，是谓灾眚。</p><h3 id="本义-14" tabindex="-1">本义 <a class="header-anchor" href="#本义-14" aria-label="Permalink to “本义”">​</a></h3><p>六以阴居动体之上，处阴过之极，过之已高而甚远者也，故其象占如此。或曰“遇过”恐亦只当作“过遇”，义同九四，未知是否。</p><h3 id="程传-17" tabindex="-1">程传 <a class="header-anchor" href="#程传-17" aria-label="Permalink to “程传”">​</a></h3><p>六阴而动体，处过之极，不与理遇，动皆过之。其违理过常，如飞鸟之迅速，所以凶也。离过之远，是谓灾眚，是当有灾眚也。灾者，天殃；眚者，人为。既过之极，岂惟人眚，天灾亦至，其凶可知。天理人事皆然也。</p><h3 id="集说-15" tabindex="-1">集说 <a class="header-anchor" href="#集说-15" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>王氏弼曰：小人之过，遂至上极。过而不知限，至于亢也。过至于亢，将何所遇？飞而不将，何所托？灾已自致，复何言哉。</p></li><li><p>孔氏颖达曰：以小人之身，过而弗遇，必遭罗网。其犹鸟飞而无托，必离缯缴，故曰“飞鸟离之凶也”。过亢离凶，是谓自灾而致眚。</p></li><li><p>胡氏瑗曰：上六过而不已，若鸟之高翔，不知所止，以至穷极而离于凶祸，不能反于下以图其所安。犹人之不近人情，亢已而行，故外来之灾自招之，损皆有之也。</p></li><li><p>余氏芑舒曰：飞鸟离之，如鸿则离之之离。</p></li><li><p>俞氏琰曰：彖辞言“不宜上而上”，乃震动之体，动极而忘返，如飞鸟离于缯缴，不亦凶乎？是天灾也，亦人眚也，故曰“飞鸟离之凶，是谓灾眚”。</p></li></ul><h3 id="案-10" tabindex="-1">案 <a class="header-anchor" href="#案-10" aria-label="Permalink to “案”">​</a></h3><p>复之上曰“迷复凶，有灾眚”，此曰“飞鸟离之凶，是谓灾眚”。辞意不同，凶由己作，灾眚外至。迷复则因凶而致灾眚者也，此则凶即其灾眚也。盖时当过极，不能自守而徇俗，以至于此。与初六当时未过而自飞以致凶者稍别。</p><p>象曰：弗遇过之，已亢也</p><h3 id="程传-18" tabindex="-1">程传 <a class="header-anchor" href="#程传-18" aria-label="Permalink to “程传”">​</a></h3><p>居过之终，弗遇于理，而过之，过已亢，极其凶宜也。</p><h3 id="集说-16" tabindex="-1">集说 <a class="header-anchor" href="#集说-16" aria-label="Permalink to “集说”">​</a></h3><ul><li><p>孔氏颖达曰 ：释所以弗遇过之，以其已在亢极之地故也。</p></li><li><p>赵氏汝梅曰 ：已上未为极，已亢则极矣。</p></li><li><p>俞氏琰曰 ：六五曰已上，谓其已过也；上六又过甚，故曰已亢。</p></li></ul><p>总论</p><ul><li><p>项氏安世曰：坎离者，乾坤之用也。故上经终于坎离，下经终于既未济。颐中孚肖离，大小过肖坎。故上经以颐大过附坎离，下经以中孚小过附既未济。二阳函四阴则谓之颐，四阳函二阴则谓之中孚，二阴函四阳则谓之大过，四阴函二阳则谓之小过。离之为丽，坎之为陷，意亦类此。</p></li><li><p>吴氏曰：以二阳言，九三过刚居上，不能自下，故或戕之；九四居柔能下，故无咎。五上皆以阴乘阳，上彖传所谓“上逆”者也。曰已上，曰已亢，然上凶而五不然者，以其柔中也。六二柔顺中正而承乎阳，所谓“下顺”者也，故无咎。初以柔居下而凶者，位虽卑而志则上而不下，是以与上六同为飞鸟之象也。</p></li></ul>',146)])])}const m=l(h,[["render",p]]);export{b as __pageData,m as default};
